//! Full frozen originals, shared unique legacy delegates and native complete DATA.
#[path="../fixtures/original_policies/cross_sys_requirements.rs"]mod old_requirements;
#[path="../fixtures/original_policies/cross_sys_dx_string_names.rs"]mod old_names;
#[path="../fixtures/native-cross-sys/fixture.rs"]mod fixture;
use crate::{captured_raw_tree_pages::{Policy,Data},captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},captured_reactive_reads::Failure};
use std::{path::Path,sync::Arc,io};
fn policy(kind:&str)->Policy{match kind{"requirements"=>Policy::Requirements,"dx_string_names"=>Policy::StringNames,_=>panic!("actual policy")}}
struct Pages<'a>{root:&'a Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:Arc<Budget>,stop:bool}
impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,RawPolicyViews<'_>)->Result<bool,Failure>)->Result<bool,Failure>{if self.stop{return Ok(false)}for(relative,text)in &self.rows{if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(true)}}
fn pages<'a>(root:&'a Path,budget:&Arc<Budget>,kind:&str,case:usize)->Pages<'a>{let mut rows=Vec::new();for(relative,text)in fixture::files(kind,case){if policy(kind).selects_path(relative){let original=dm_preprocess::AcquiredSource::from_original_bytes(text.into_bytes(),());rows.push((relative.to_string(),original.lease().source_text().clone()));}}rows.reverse();Pages{root,rows,budget:Arc::clone(budget),stop:false}}
struct Text<'a>(&'a Data);impl crate::baseline::SiteText for Text<'_>{fn site_text(&self,relative:&str,line:usize)->String{self.0.sites().iter().zip(self.0.source_text()).find(|(s,_)|s.rel==relative&&s.line as usize==line).expect("actual current line").1.clone()}}
fn record(outcome:&crate::policy_finish::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
fn old_register(kind:&str,r:&mut crate::lint::Registry){match kind{"requirements"=>old_requirements::register(r),"dx_string_names"=>old_names::register(r),_=>panic!("kind")}}
fn new_register(kind:&str,r:&mut crate::lint::Registry){match kind{"requirements"=>crate::lints::sys_requirements::register(r),"dx_string_names"=>crate::lints::sys_dx_string_names::register(r),_=>panic!("kind")}}
#[test]fn cross_sys_ten_full_frozen_original_shared_native_reports_preserve_scopes_fallback_last_definition_and_allow(){use sha1::Digest as _;assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/cross_sys_requirements.rs"))),"9014882caa7b415cfb3926666962b502796a664d");assert_eq!(format!("{:x}",sha1::Sha1::digest(include_bytes!("../fixtures/original_policies/cross_sys_dx_string_names.rs"))),"9a5e692708b767bd8badf9b38531d58960cf349a");for kind in fixture::KINDS{for case in 0..5{let root=crate::test_scratch::dir(&format!("cross-sys-{kind}-{case}"));for(relative,text)in fixture::files(kind,case){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}let configuration=fixture::configuration(kind,case);let path=root.join("tools/ci/lint_scopes.toml");std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,&configuration).unwrap();let options=crate::run::Options{root:root.clone(),lints:vec![fixture::name(kind).into()],raw:true,no_cache:true,..Default::default()};let mut reg=crate::lint::Registry::default();old_register(kind,&mut reg);let old=crate::run::Engine::new(reg,options.clone()).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());assert!(expected.internal_error.is_none());let mut reg=crate::lint::Registry::default();new_register(kind,&mut reg);let shared=crate::run::Engine::new(reg,options).unwrap();assert_eq!(record(&shared.run_one(shared.reg.lints[0].as_ref())),record(&expected),"entire original/shared {kind}/{case}");if case==0{assert!(!expected.run.sites.is_empty(),"falsifiable actual old positive {kind}");assert!(expected.run.sites.iter().any(|s|s.rel=="maps/decl.dm"));assert!(!expected.run.sites.iter().any(|s|s.rel.contains(".hidden")||s.rel.contains("unit_tests")));assert!(!expected.allow_used.is_empty());}
 let b=Budget::new(128*1024*1024).unwrap();let config=Config::capture(crate::captured_raw_policy::Configuration::Captured(configuration.as_bytes())).unwrap();let selected=policy(kind);let data=crate::captured_raw_tree_pages::collect(&pages(&root,&b,kind,case),selected,&config,&b,&||Ok(())).unwrap();assert_eq!(data.sites(),expected.run.sites.as_slice(),"every original site {kind}/{case}");assert_eq!(data.allow_used(),expected.allow_used.as_slice());assert_eq!(data.notes(),expected.run.notes.as_slice());for(s,text)in data.sites().iter().zip(data.source_text()){assert_eq!(*text,old.tree.site_text(&s.rel,s.line as usize));}let empty=Default::default();let scope=config.borrowed_report_scope(fixture::name(kind),"sys").unwrap_or(&empty);let actual=crate::policy_finish::finish_report(selected.metadata(),scope,&Text(&data),crate::lint::Run{sites:data.sites().to_vec(),notes:data.notes().to_vec()},data.allow_used().to_vec(),Default::default(),&root,&None,true,|_,_,_|panic!("actual ordinary Sites producer has no custom hook"),|_,_|false);assert_eq!(record(&actual),record(&expected),"whole original/native report {kind}/{case}");println!("CROSS_SYS_WHOLE_ORIGINAL_NATIVE={}",serde_json::json!({"kind":kind,"case":case,"record":record(&actual)}));}}}
#[test]fn cross_sys_typed_growth_and_mid_source_actual_1450_refuse_then_recover_without_source_authority(){let root=std::env::current_dir().unwrap().join("cross-sys-checked-source");let b=Budget::new(256*1024*1024).unwrap();let mut count_files=0;for kind in fixture::KINDS{let config=Config::capture(crate::captured_raw_policy::Configuration::Captured(fixture::configuration(kind,0).as_bytes())).unwrap();let mut source=pages(&root,&b,kind,0);source.stop=true;assert!(matches!(crate::captured_raw_tree_pages::collect(&source,policy(kind),&config,&b,&||Ok(())),Err(Failure::Unsupported(message))if message.contains("EOF")));source.stop=false;assert!(!crate::captured_raw_tree_pages::collect(&source,policy(kind),&config,&b,&||Ok(())).unwrap().sites().is_empty());}
 crate::captured_raw_file::with_original_policy_file(&root,&root.join("code/admitted.dm"),format!("DECLARE_INTERACTIONS(/obj/control, \\\n{}\n)\n/proc/own_widget(datum/H, var_name, datum/V)\n\treturn\n{}","    INTERACT_HAND(\"Use\", PROC_REF(use_widget)) \\\n".repeat(256),(0..256).map(|n|format!("/proc/own_entry_{n}(datum/H, var_name, datum/V)\n\treturn\n")).collect::<String>()).into(),0,&b,&mut|_,views|{let f=views.source_file()?;let denied=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let mut keep=crate::captured_allow_annotations::Operation{budget:&denied,poll:&||Ok(())};let mut temp=crate::captured_allow_annotations::Operation{budget:&b,poll:&||Ok(())};assert!(matches!(crate::sys_requirements_policy::effects_of_using(f,&mut keep,&mut temp),Err(Failure::Operational(ref e))if e.kind()==io::ErrorKind::OutOfMemory));let denied=Budget::new(std::mem::size_of::<Budget>()+2*std::mem::size_of::<usize>()).unwrap();let mut keep=crate::captured_allow_annotations::Operation{budget:&denied,poll:&||Ok(())};assert!(matches!(crate::sys_string_names_policy::file_accessors(f,&mut keep,&mut temp),Err(Failure::Operational(ref e))if e.kind()==io::ErrorKind::OutOfMemory));let calls=std::cell::Cell::new(0usize);let poll=||{let n=calls.get()+1;calls.set(n);if n==32{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}};let mut keep=crate::captured_allow_annotations::Operation{budget:&b,poll:&poll};assert!(matches!(crate::sys_requirements_policy::effects_of_using(f,&mut keep,&mut temp),Err(Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));assert_eq!(calls.get(),32);calls.set(0);let mut keep=crate::captured_allow_annotations::Operation{budget:&b,poll:&poll};assert!(matches!(crate::sys_string_names_policy::file_accessors(f,&mut keep,&mut temp),Err(Failure::Operational(ref e))if e.raw_os_error()==Some(1450)));assert_eq!(calls.get(),32);let mut keep=crate::captured_allow_annotations::Operation{budget:&b,poll:&||Ok(())};assert!(!crate::sys_requirements_policy::effects_of_using(f,&mut keep,&mut temp)?.is_empty());assert!(!crate::sys_string_names_policy::file_accessors(f,&mut keep,&mut temp)?.is_empty());count_files+=1;Ok(true)}).unwrap();assert_eq!(count_files,1);}
